parameters.jsCode:
return $input.all().map((item, index) => {
  const healthy = item.json.recovery === 'healthy';
  return {
    json: {
      ...item.json,
      phase: 'maintenance-end',
      decision: healthy ? 'preview-completion' : 'hold-maintenance',
      proposed_actions: healthy
        ? ['Disable the pre-created maintenance rule', 'Complete the status incident', 'Notify customers and operations']
        : ['Keep maintenance mode enabled', 'Keep the status incident open', 'Alert operations and recheck recovery'],
    },
    pairedItem: { item: index },
  };
});

return $input.all().map(({ json: response }, index) => {
  const occurrence = $('Prepare occurrence context').itemMatching(index).json;
  const expected = $('Configure maintenance actions').itemMatching(index).json.healthy_status;
  const final = occurrence.target_id === 'maintenance-end';
  const end = $node['Schedule the maintenance window'].parameter.windowEnd;
  const matchesEnd = !final || Date.parse(end) === Date.parse(occurrence.scheduled_for);
  const status = response.statusCode ?? null;
  const healthy = !response.error && status === expected && matchesEnd;
  return {
    json: {
      ...occurrence,
      health_status: status,
      health_expected_status: expected,
      health_ok: healthy,
      decision: healthy ? (final ? 'recovery-confirmed' : 'healthy-progress') : 'health-check-failed',
      health_error: !matchesEnd ? 'The occurrence does not match the configured end time.'
        : response.error ? 'The health endpoint could not be reached.'
        : healthy ? null : `Expected HTTP ${expected}, received ${status ?? 'no status'}.`,
    },
    pairedItem: { item: index },
  };
});

const schedule = $node['Schedule the maintenance window'].parameter;
const audiences = schedule.audiences?.audience ?? [];
const emailPattern = /^[^\s@,]+@[^\s@,]+\.[^\s@,]+$/;

function message(locale, service, start, end, recovery) {
  const language = locale.split('-')[0].toLowerCase();
  if (language === 'fr') {
    return recovery
      ? [`${service} – reprise du service`, `La maintenance de ${service} est terminée. Le service est de nouveau disponible.`]
      : [`${service} – maintenance programmée`, `Une maintenance de ${service} est prévue du ${start} au ${end} (heure locale).`];
  }
  if (language === 'ja') {
    return recovery
      ? [`${service} – サービス復旧のお知らせ`, `${service}のメンテナンスが完了し、サービスが復旧しました。`]
      : [`${service} – メンテナンスのお知らせ`, `${service}のメンテナンスを${start}から${end}まで（現地時間）実施します。`];
  }
  return recovery
    ? [`${service} – service restored`, `Maintenance for ${service} is complete and the service is available again.`]
    : [`${service} – scheduled maintenance`, `Maintenance for ${service} is scheduled from ${start} to ${end} (local time).`];
}

return $input.all().flatMap(({ json: occurrence }, index) => {
  const reminder = occurrence.target_id.match(/^customer-reminder-(?:7d|1d)-(.+)$/);
  const recovery = occurrence.target_id === 'maintenance-end' && occurrence.health_ok === true;
  if (occurrence.mode !== 'live' || !occurrence.occurrence_key || (!reminder && !recovery)) return [];

  const config = $('Configure maintenance actions').itemMatching(index).json;
  const selected = recovery ? audiences : audiences.filter(audience => audience.id === reminder[1]);
  if (!selected.length) throw new Error('The notice has no matching audience on the Event Window trigger.');
  const recipients = new Map();
  for (const audience of selected) {
    const addresses = config.regional_recipients?.[audience.id] ?? [];
    if (!Array.isArray(addresses) || addresses.some(email => typeof email !== 'string' || !emailPattern.test(email.trim()))) {
      throw new Error(`Enter an array of valid email addresses for ${audience.id} in regional_recipients.`);
    }
    for (const address of addresses) {
      const email = address.trim().toLowerCase();
      if (!recipients.has(email)) recipients.set(email, audience);
    }
  }
  if (!recipients.size) return [];
  const sender = config.sender_email?.trim();
  const service = config.service_name?.trim();
  if (!emailPattern.test(sender ?? '') || !service) {
    throw new Error('Configure a verified Brevo sender_email and a service_name.');
  }
  return [...recipients].map(([email, audience]) => {
    const locale = JSON.parse(audience.metadata || '{}').locale || 'en';
    const format = new Intl.DateTimeFormat(locale, {
      dateStyle: 'medium', timeStyle: 'long', timeZone: audience.timezone,
    });
    const start = recovery ? '' : format.format(new Date(schedule.windowStart));
    const end = recovery ? '' : format.format(new Date(schedule.windowEnd));
    const [subject, textContent] = message(locale, service, start, end, recovery);
    const sandbox = config.brevo_sandbox !== false;
    return {
      json: {
        target_id: occurrence.target_id,
        occurrence_key: occurrence.occurrence_key,
        delivery_key: JSON.stringify([occurrence.occurrence_key, email, sandbox]),
        brevo_sandbox: sandbox,
        email: { sender: { email: sender }, to: [{ email }], subject, textContent },
      },
      pairedItem: { item: index },
    };
  });
});

return $input.all().map(({ json: response }, index) => {
  const notice = $('Prepare Brevo notice').itemMatching(index).json;
  const duplicate = response.statusCode === 400
    && response.body?.code === 'duplicate_parameter'
    && /idempotency/i.test(response.body?.message ?? '');
  const messageId = response.body?.messageId ?? null;
  if (!duplicate && (response.statusCode !== 201 || !messageId)) {
    throw new Error(`Brevo did not accept the ${notice.target_id} notice (HTTP ${response.statusCode ?? 'unknown'}).`);
  }
  return {
    json: {
      target_id: notice.target_id,
      occurrence_key: notice.occurrence_key,
      message_id: messageId,
      delivery: duplicate ? 'duplicate-skipped' : notice.brevo_sandbox ? 'sandbox-accepted' : 'accepted',
    },
    pairedItem: { item: index },
  };
});

const schedule = $node['Schedule the maintenance window'].parameter;

function resource(settings, names, pattern, service) {
  const values = names.map(name => String(settings?.[name] ?? '').trim());
  if (values.every(value => !value)) return null;
  if (values.some(value => !pattern.test(value))) {
    throw new Error(`Set all ${service} IDs in Configure maintenance actions, or leave them all blank.`);
  }
  return values;
}

return $input.all().flatMap(({ json: occurrence }, index) => {
  const start = occurrence.target_id === 'maintenance-start';
  const recovery = occurrence.target_id === 'maintenance-end' && occurrence.health_ok === true;
  if (occurrence.mode !== 'live' || !occurrence.occurrence_key || (!start && !recovery)) return [];
  const boundary = start ? schedule.windowStart : schedule.windowEnd;
  if (Date.parse(occurrence.scheduled_for) !== Date.parse(boundary)) {
    throw new Error('The occurrence does not match the configured maintenance boundary.');
  }
  if (start && Date.now() >= Date.parse(schedule.windowEnd)) {
    throw new Error('The maintenance window has already ended. The start action was skipped.');
  }
  const config = $('Configure maintenance actions').itemMatching(index).json;
  const cloudflare = resource(config.cloudflare, ['zone_id', 'ruleset_id', 'rule_id'], /^[a-f0-9]{32}$/i, 'Cloudflare');
  const statuspage = resource(config.statuspage, ['page_id', 'incident_id'], /^[a-z0-9]+$/i, 'Statuspage');
  return {
    json: {
      ...occurrence,
      cloudflare_ruleset_url: cloudflare
        ? `https://api.cloudflare.com/client/v4/zones/${cloudflare[0]}/rulesets/${cloudflare[1]}` : null,
      cloudflare_rule_id: cloudflare?.[2] ?? null,
      cloudflare_enabled: start,
      statuspage_url: statuspage
        ? `https://api.statuspage.io/v1/pages/${statuspage[0]}/incidents/${statuspage[1]}` : null,
      statuspage_incident_id: statuspage?.[1] ?? null,
      statuspage_status: start ? 'in_progress' : 'completed',
    },
    pairedItem: { item: index },
  };
});

const schedule = $node['Schedule the maintenance window'].parameter;
return $input.all().map(({ json: incident }, index) => {
  const transition = $('Prepare maintenance transition').itemMatching(index).json;
  if (incident.id !== transition.statuspage_incident_id
    || Date.parse(incident.scheduled_for) !== Date.parse(schedule.windowStart)
    || Date.parse(incident.scheduled_until) !== Date.parse(schedule.windowEnd)) {
    throw new Error('The Statuspage maintenance ID or window does not match Event Window.');
  }
  if (incident.scheduled_auto_in_progress === true || incident.scheduled_auto_completed === true) {
    throw new Error('Turn off automatic start and completion for this Statuspage maintenance.');
  }
  if (transition.statuspage_status === 'in_progress' && Date.now() >= Date.parse(schedule.windowEnd)) {
    throw new Error('The maintenance window ended before Statuspage could start.');
  }
  const allowed = transition.statuspage_status === 'in_progress'
    ? ['scheduled', 'in_progress'] : ['in_progress', 'verifying', 'completed'];
  if (!allowed.includes(incident.status)) {
    throw new Error(`Cannot move Statuspage maintenance from ${incident.status} to ${transition.statuspage_status}.`);
  }
  const componentStatus = transition.statuspage_status === 'in_progress'
    ? 'under_maintenance' : 'operational';
  const components = incident.components ?? [];
  const componentStates = Object.fromEntries(components.map(component => [component.id, componentStatus]));
  const updateComponents = components.some(component => component.status !== componentStatus);
  return {
    json: {
      ...transition,
      statuspage_components: componentStates,
      update_statuspage: incident.status !== transition.statuspage_status || updateComponents,
    },
    pairedItem: { item: index },
  };
});

return $input.all().map(({ json: response }, index) => {
  const transition = $('Use Cloudflare').itemMatching(index).json;
  const rule = response.result?.rules?.find(entry => entry.id === transition.cloudflare_rule_id);
  if (response.success !== true || !rule || !['block', 'redirect'].includes(rule.action) || !rule.expression) {
    throw new Error('Select an existing Cloudflare Block or Redirect maintenance rule.');
  }
  if (transition.cloudflare_enabled && Date.now() >= Date.parse($node['Schedule the maintenance window'].parameter.windowEnd)) {
    throw new Error('The maintenance window ended before the Cloudflare rule could be enabled.');
  }
  const { id, last_updated, version, ...definition } = rule;
  return {
    json: {
      ...transition,
      update_cloudflare: (rule.enabled ?? true) !== transition.cloudflare_enabled,
      cloudflare_patch: { ...definition, enabled: transition.cloudflare_enabled },
    },
    pairedItem: { item: index },
  };
});

return $input.all().map(({ json: response }, index) => {
  const transition = $('Use Cloudflare').itemMatching(index).json;
  const rule = response.result?.rules?.find(entry => entry.id === transition.cloudflare_rule_id);
  if (response.success !== true || !rule || rule.enabled !== transition.cloudflare_enabled) {
    throw new Error('Cloudflare did not confirm the expected rule state.');
  }
  return { json: transition, pairedItem: { item: index } };
});

