return $input.all().map(({ json: incident }, index) => {
  const transition = $('Update Statuspage').itemMatching(index).json;
  const componentsMatch = Object.entries(transition.statuspage_components ?? {}).every(([id, status]) =>
    incident.components?.some(component => component.id === id && component.status === status));
  if (incident.id !== transition.statuspage_incident_id
    || incident.status !== transition.statuspage_status || !componentsMatch) {
    throw new Error('Statuspage did not confirm the expected maintenance and component statuses.');
  }
  return { json: transition, pairedItem: { item: index } };
});

const messages = {
  'ops-warning-2h': 'Maintenance starts in two hours. Review readiness and dependencies.',
  'ops-warning-15m': 'Maintenance starts in fifteen minutes. Run the final preflight.',
  'maintenance-start': 'Scheduled maintenance is in progress.',
  'maintenance-end': 'The final health check passed. Maintenance is complete.',
};

return $input.all().map(({ json: occurrence }, index) => {
  const config = $('Configure maintenance actions').itemMatching(index).json;
  const channel = config.slack_channel_id?.trim() ?? '';
  const message = occurrence.health_ok === false
    ? `Maintenance health check failed (${occurrence.target_id}). ${occurrence.health_error}`
    : messages[occurrence.target_id];
  return {
    json: {
      ...occurrence,
      slack_channel: channel,
      slack_text: message ? `[${config.service_name}] ${message} (${occurrence.scheduled_for})` : null,
    },
    pairedItem: { item: index },
  };
});

return $input.all().map(({ json: response }, index) => {
  const occurrence = $('Prepare Slack message').itemMatching(index).json;
  const error = response.ok === true ? null : (typeof response.error === 'string' ? response.error : 'Request failed.');
  if (error && typeof occurrence.health_ok !== 'boolean') {
    throw new Error(`Slack message failed for ${occurrence.target_id}. ${error}`);
  }
  return {
    json: { ...occurrence, slack_error: error },
    pairedItem: { item: index },
  };
});
